                    .lineLimit(1)

                // Alphabet & Numbers specimen
                Text(LocalizedStrings.translateText("ABCDEFGHIJKLMNOPQRSTUVWXYZ  abcdefghijklmnopqrstuvwxyz  0123456789", lang: appLanguage))
