            UserDefaults.standard.set("Genie Lamp", forKey: "nexus.brandIconStyle")
            UserDefaults.standard.set("Genie Lamp", forKey: "nexus.statusIconStyle")
        } else {
            self.brandIconStyle = savedStyle
        }

        let savedVisible = UserDefaults.standard.object(forKey: "nexus.brandIconEnabled") == nil
            ? (UserDefaults.standard.object(forKey: "nexus.iconEnabled") == nil ? true : UserDefaults.standard.bool(forKey: "nexus.iconEnabled"))
            : UserDefaults.standard.bool(forKey: "nexus.brandIconEnabled")
        self.isBrandIconVisible = savedVisible

        loadCustomLogoFromDisk()
    }

    // MARK: - Revert & Reset Actions

    func resetToDefaultGenie() {
        customLogoImage = nil
        brandIconStyle = "Genie Lamp"
        UserDefaults.standard.set("Genie Lamp", forKey: "nexus.brandIconStyle")
        UserDefaults.standard.set("Genie Lamp", forKey: "nexus.statusIconStyle")
        UserDefaults.standard.removeObject(forKey: "nexus.customBrandLogoPath")
